(7292984, 1137200, 30861, '<td valign="top">This si absolutely beautiful. It may not have enough punch in the tonalities to do well, but I appreciate it very much. 10 from me to start my voting :-)</td>', 'This si absolutely beautiful. It may not have enough punch in the tonalities to do well, but I appreciate it very much. 10 from me to start my voting :-)', '2014-12-15 00:19:08.000000', NULL, 1),
(7293004, 1137099, 60173, '<td valign="top">That''s a cute idea.</td>', 'That''s a cute idea.', '2014-12-15 01:39:09.000000', NULL, 1),
(7293008, 1136949, 83313, '<td valign="top">Love this! Textures are great and the touch of reddish brown is just enough.</td>', 'Love this! Textures are great and the touch of reddish brown is just enough.', '2014-12-15 02:04:32.000000', NULL, 1),
(7293009, 1137089, 83313, '<td valign="top">Thank you for breaking up the endless procession of flower shots.</td>', 'Thank you for breaking up the endless procession of flower shots.', '2014-12-15 02:08:26.000000', NULL, 1),
(7293013, 1136945, 40391, '<td valign="top">Not what one would normally expect to see in a botany challenge so for that, thank you. But this is a beautiful image in any challenge and is my top pick.</td>', 'Not what one would normally expect to see in a botany challenge so for that, thank you. But this is a beautiful image in any challenge and is my top pick.', '2014-12-15 03:39:23.000000', NULL, 1),
