(7293282, 1136916, 109227, '<td valign="top">Nice light and comp.</td>', 'Nice light and comp.', '2014-12-15 20:38:33.000000', NULL, 1),
(7293283, 1137023, 109227, '<td valign="top">Nice find and photographed and composed well.  A little bit of over sharpening is showing up, but still a nice image.</td>', 'Nice find and photographed and composed well.  A little bit of over sharpening is showing up, but still a nice image.', '2014-12-15 20:40:24.000000', NULL, 1),
