(7293290, 1137049, 109227, '<td valign="top">Beautiful "Angel Wing".  Nice lighting.</td>', 'Beautiful "Angel Wing".  Nice lighting.', '2014-12-15 20:43:23.000000', NULL, 1),
(7293291, 1137120, 109227, '<td valign="top">This looks like ballerinas with no heads, lol.  The simplicity and softness is nice.</td>', 'This looks like ballerinas with no heads, lol.  The simplicity and softness is nice.', '2014-12-15 20:44:12.000000', NULL, 1),
(7293292, 1137069, 109227, '<td valign="top">Nice fine; I would like to see the center and petals a little more in focus.</td>', 'Nice fine; I would like to see the center and petals a little more in focus.', '2014-12-15 20:44:53.000000', NULL, 1),
(7293293, 1137089, 109227, '<td valign="top">Great detail and light.  Tiny??  You always make me laugh.</td>', 'Great detail and light.  Tiny??  You always make me laugh.', '2014-12-15 20:45:38.000000', NULL, 1),
