(7293583, 1136832, 159196, '<td valign="top">Striking - in my top 3</td>', 'Striking - in my top 3', '2014-12-17 05:10:45.000000', NULL, 1),
(7293584, 1137118, 159196, '<td valign="top">I love the mood, the light, the mist - you''ve achieved an almost 3D effect. Great title too. My favorite in this challenge. Good luck</td>', 'I love the mood, the light, the mist - you''ve achieved an almost 3D effect. Great title too. My favorite in this challenge. Good luck', '2014-12-17 05:12:32.000000', NULL, 1),
(7293585, 1137034, 159196, '<td valign="top">Stunning - in my top 3. Good luck!</td>', 'Stunning - in my top 3. Good luck!', '2014-12-17 05:13:01.000000', NULL, 1),
(7293586, 1137125, 159196, '<td valign="top">Love the green fern in contrast to the rest, and the green moss echo at the top. In my top 5. Good luck!</td>', 'Love the green fern in contrast to the rest, and the green moss echo at the top. In my top 5. Good luck!', '2014-12-17 05:15:08.000000', NULL, 1),
(7293587, 1137138, 159196, '<td valign="top">Beautiful colors, shapes and depth. In my top 5</td>', 'Beautiful colors, shapes and depth. In my top 5', '2014-12-17 05:16:34.000000', NULL, 1),
(7293598, 1137152, 35804, '<td valign="top">A pleasing simplcity.</td>', 'A pleasing simplcity.', '2014-12-17 08:25:38.000000', NULL, 1),
(7293730, 1137164, 60495, '<td valign="top">I love the one branch with the berrys and think the shot would be really nice with just that brach, the rest of thebranches just make the image a little cluttered. What I really like is the contrasting background with the nice bokeh.</td>', 'I love the one branch with the berrys and think the shot would be really nice with just that brach, the rest of thebranches just make the image a little cluttered. What I really like is the contrasting background with the nice bokeh.', '2014-12-17 18:30:00.000000', NULL, 1),
(7293752, 1136949, 114285, '<td valign="top">Brilliant rendition, one of my faves.</td>', 'Brilliant rendition, one of my faves.', '2014-12-17 21:26:03.000000', NULL, 1),
(7293753, 1137153, 114285, '<td valign="top">Amazing shot, love the editing as well!</td>', 'Amazing shot, love the editing as well!', '2014-12-17 21:27:04.000000', NULL, 1),
(7293754, 1137209, 114285, '<td valign="top">Right up there as one of the best on here, amazing perspective well done!!</td>', 'Right up there as one of the best on here, amazing perspective well done!!', '2014-12-17 21:29:25.000000', NULL, 1),
(7293769, 1137034, 179524, '<td valign="top">This is exceptionally beautiful.</td>', 'This is exceptionally beautiful.', '2014-12-18 06:49:22.000000', NULL, 1),
(7293981, 1136914, 114225, '<td valign="top">I find this interesting.</td>', 'I find this interesting.', '2014-12-18 22:40:31.000000', NULL, 1),
(7293982, 1137134, 114225, '<td valign="top">What great color.</td>', 'What great color.', '2014-12-18 22:41:06.000000', NULL, 1),
(7294049, 1137066, 114285, '<td valign="top">Incredible photo.</td>', 'Incredible photo.', '2014-12-19 02:38:41.000000', NULL, 1),
(7294050, 1137118, 114285, '<td valign="top">Now this is my kind of photo, foggy and black and white.<br/>In my top 3.</td>', 'Now this is my kind of photo, foggy and black and white.In my top 3.', '2014-12-19 02:40:40.000000', NULL, 1),
(7294255, 1137029, 150277, '<td valign="top">Not sure I loved the silver background, the green and brown against silver just didn''t seem to meld happily in my brain.  But great capture of a pineapple and the lighting is nice.</td>', 'Not sure I loved the silver background, the green and brown against silver just didn''t seem to meld happily in my brain.  But great capture of a pineapple and the lighting is nice.', '2014-12-19 16:11:01.000000', NULL, 1),
(7294313, 1137156, 176157, '<td valign="top"><u></u></td>', '', '2014-12-19 20:06:17.000000', NULL, 1),
(7294350, 1137209, 156466, '<td valign="top">Love this a lot...except for two branches/twigs that keep me from giving it a 10.</td>', 'Love this a lot...except for two branches/twigs that keep me from giving it a 10.', '2014-12-20 06:46:41.000000', NULL, 1),
(7294351, 1137186, 156466, '<td valign="top">Like the idea and composition, but not the unevenness and directness of the lighting.</td>', 'Like the idea and composition, but not the unevenness and directness of the lighting.', '2014-12-20 06:47:39.000000', NULL, 1),
(7294353, 1137069, 156466, '<td valign="top">Given that you''ve titled it for the web I would have liked some more depth of field.</td>', 'Given that you''ve titled it for the web I would have liked some more depth of field.', '2014-12-20 06:48:49.000000', NULL, 1),
(7294354, 1137020, 156466, '<td valign="top">Edit feels a little heavy handed</td>', 'Edit feels a little heavy handed', '2014-12-20 06:49:25.000000', NULL, 1),
(7294355, 1137018, 156466, '<td valign="top">Love the light variation on the fern.</td>', 'Love the light variation on the fern.', '2014-12-20 06:49:50.000000', NULL, 1),
(7294357, 1136832, 156466, '<td valign="top">Could have used just a touch more D0F on the body of the flower.</td>', 'Could have used just a touch more D0F on the body of the flower.', '2014-12-20 06:50:43.000000', NULL, 1),
(7294358, 1137162, 156466, '<td valign="top">Can''t tell if it''s over sharpened, over textured or both.  Not pleasing to my eye.</td>', 'Can''t tell if it''s over sharpened, over textured or both.  Not pleasing to my eye.', '2014-12-20 06:52:56.000000', NULL, 1),
(7294359, 1136927, 156466, '<td valign="top">I might have gotten rid of the long web on the left as it distracts the eye (the others, not so much).  Great detail otherwise.</td>', 'I might have gotten rid of the long web on the left as it distracts the eye (the others, not so much).  Great detail otherwise.', '2014-12-20 06:54:12.000000', NULL, 1),
(7294360, 1137099, 156466, '<td valign="top">Great idea, but the line of the stem, and other leaves, distract from the overall composition just enough to make me say, "Great idea, but you didn''t nail it".  Perhaps without the extra leaves?</td>', 'Great idea, but the line of the stem, and other leaves, distract from the overall composition just enough to make me say, "Great idea, but you didn''t nail it".  Perhaps without the extra leaves?', '2014-12-20 06:56:23.000000', NULL, 1),
(7294361, 1137123, 156466, '<td valign="top">Perhaps a little blur added to soften the bokeh?  Structure/clarity adjustment in the OOF regions distract from the delicate nature of the rest of the shot.</td>', 'Perhaps a little blur added to soften the bokeh?  Structure/clarity adjustment in the OOF regions distract from the delicate nature of the rest of the shot.', '2014-12-20 06:58:22.000000', NULL, 1),
(7294362, 1137121, 156466, '<td valign="top">Would have loved it if you had been able to extract that thread first.  Still very cool.</td>', 'Would have loved it if you had been able to extract that thread first.  Still very cool.', '2014-12-20 06:59:24.000000', NULL, 1),
(7294363, 1137034, 156466, '<td valign="top">Stunning.  Nicely shot and processed.</td>', 'Stunning.  Nicely shot and processed.', '2014-12-20 06:59:43.000000', NULL, 1),
(7294364, 1137009, 156466, '<td valign="top">The flower is lovely and well processed.  The background noise is utterly distracting, and while I understand that the rules won''t let you remove them I wish you had softened them a bunch.  6 that could have been 9.</td>', 'The flower is lovely and well processed.  The background noise is utterly distracting, and while I understand that the rules won''t let you remove them I wish you had softened them a bunch.  6 that could have been 9.', '2014-12-20 07:01:15.000000', NULL, 1),
(7294365, 1137155, 156466, '<td valign="top">Great details.</td>', 'Great details.', '2014-12-20 07:02:32.000000', NULL, 1),
(7294366, 1137062, 156466, '<td valign="top">Lovely colors, composition, details and background, but the ISO noise just scratches like nails on a chalk board for me.  Or maybe it''s artifacts from a structure/clarity adjustment?  It bothers me less on the flowers and post than it does in what I''d want to be a soft and very OOF background, but instead my eye focuses on the artifacts and not the wash.  Another 6 that could have been 9.</td>', 'Lovely colors, composition, details and background, but the ISO noise just scratches like nails on a chalk board for me.  Or maybe it''s artifacts from a structure/clarity adjustment?  It bothers me less on the flowers and post than it does in what I''d want to be a soft and very OOF background, but instead my eye focuses on the artifacts and not the wash.  Another 6 that could have been 9.', '2014-12-20 07:06:58.000000', NULL, 1),
(7294367, 1137093, 156466, '<td valign="top">Nice wash of colors, but my eye wants something to lock onto as it keeps darting from one leaf to the next.  Would make a nice puzzle. :)</td>', 'Nice wash of colors, but my eye wants something to lock onto as it keeps darting from one leaf to the next.  Would make a nice puzzle. :)', '2014-12-20 07:08:34.000000', NULL, 1),
(7294368, 1137164, 156466, '<td valign="top">I''m not one to complain about composition generally, but the dead-center berries don''t work for me, particularly with the edge of the leaf cut off.</td>', 'I''m not one to complain about composition generally, but the dead-center berries don''t work for me, particularly with the edge of the leaf cut off.', '2014-12-20 07:10:21.000000', NULL, 1),
(7294369, 1137160, 156466, '<td valign="top">Processing needed to separate the herbs from the glove.  Everything runs together.</td>', 'Processing needed to separate the herbs from the glove.  Everything runs together.', '2014-12-20 07:11:21.000000', NULL, 1),
(7294370, 1137118, 156466, '<td valign="top">Why is there always that one little tree that gets in the way?</td>', 'Why is there always that one little tree that gets in the way?', '2014-12-20 07:12:48.000000', NULL, 1),
(7294371, 1137120, 156466, '<td valign="top">Lovely - nice to see the processing match the delicate nature of the subject.</td>', 'Lovely - nice to see the processing match the delicate nature of the subject.', '2014-12-20 07:13:43.000000', NULL, 1),
(7294372, 1137134, 156466, '<td valign="top">Blues are very saturated, but still don''t quite pop as much as I''d want (luminance adjustments, perhaps?).  Maybe a little more vignetting as well to keep the eye on the subject.</td>', 'Blues are very saturated, but still don''t quite pop as much as I''d want (luminance adjustments, perhaps?).  Maybe a little more vignetting as well to keep the eye on the subject.', '2014-12-20 07:15:34.000000', NULL, 1),
(7294373, 1137090, 156466, '<td valign="top">I want to like this more than I do.  It''s just not quite right.  I''d prefer it cropped down a bit (just after the edge of the dark area in the center above the branch). Even then, the branch running through the center feels too pale.  Maybe burn in some shadows and midtones against the light background to make it really stand out against the contrast everywhere else.</td>', 'I want to like this more than I do.  It''s just not quite right.  I''d prefer it cropped down a bit (just after the edge of the dark area in the center above the branch). Even then, the branch running through the center feels too pale.  Maybe burn in some shadows and midtones against the light background to make it really stand out against the contrast everywhere else.', '2014-12-20 07:19:47.000000', NULL, 1),
(7294395, 1137090, 124982, '<td valign="top">Magnificent!  Such a powerful image!</td>', 'Magnificent!  Such a powerful image!', '2014-12-20 11:24:53.000000', NULL, 1),
(7294396, 1137054, 124982, '<td valign="top">One of my favorites. Love the minimal composition and splash of muted color.</td>', 'One of my favorites. Love the minimal composition and splash of muted color.', '2014-12-20 11:26:19.000000', NULL, 1),
(7294397, 1137118, 124982, '<td valign="top">My goodness, this is fantastic!! Top 3 from me! Lovely rich blacks and tonal range, and the depth of the image is amazing. Very captivating, well done!</td>', 'My goodness, this is fantastic!! Top 3 from me! Lovely rich blacks and tonal range, and the depth of the image is amazing. Very captivating, well done!', '2014-12-20 11:28:04.000000', NULL, 1),
(7294398, 1137200, 124982, '<td valign="top">Not sure why, but this image appeals to me greatly. Very soft, muted contrast with a matte-like haze to it. Very soothing and peaceful. One of my top images for the challenge.</td>', 'Not sure why, but this image appeals to me greatly. Very soft, muted contrast with a matte-like haze to it. Very soothing and peaceful. One of my top images for the challenge.', '2014-12-20 11:29:29.000000', NULL, 1),
(7294482, 1137099, 83149, '<td valign="top">I think it is a great idea and the main elements are very well done.  Unfortunately, things like the couch, the drapes to the shoulder and even the bra strap are distracting.  If it was shot in a studio or more pleasing setting, I would have scored it much higher.</td>', 'I think it is a great idea and the main elements are very well done.  Unfortunately, things like the couch, the drapes to the shoulder and even the bra strap are distracting.  If it was shot in a studio or more pleasing setting, I would have scored it much higher.', '2014-12-20 19:46:50.000000', NULL, 1),
(7294483, 1137069, 83149, '<td valign="top">The focus is just not doing it for me.</td>', 'The focus is just not doing it for me.', '2014-12-20 19:48:56.000000', NULL, 1),
(7294511, 1137062, 13077, '<td valign="top">Has a very island-destination postcard vibe to it.</td>', 'Has a very island-destination postcard vibe to it.', '2014-12-20 23:56:05.000000', NULL, 1),
(7294513, 1137156, 13077, '<td valign="top">Might have looked better with either a bit softer light, or some lightened shadows. The colors look fine and it is sharp, though.</td>', 'Might have looked better with either a bit softer light, or some lightened shadows. The colors look fine and it is sharp, though.', '2014-12-20 23:59:49.000000', NULL, 1),
(7294515, 1137054, 13077, '<td valign="top">The lighting looks very good on this.</td>', 'The lighting looks very good on this.', '2014-12-21 00:01:32.000000', NULL, 1),
(7294516, 1137093, 13077, '<td valign="top">A cool variety of colors, very pretty medley.</td>', 'A cool variety of colors, very pretty medley.', '2014-12-21 00:01:55.000000', NULL, 1),
(7294517, 1137163, 13077, '<td valign="top">That''s interesting with the diagonal shadows - it complements the flower well. The light on the flower itself looks a bit harsh, though.</td>', 'That''s interesting with the diagonal shadows - it complements the flower well. The light on the flower itself looks a bit harsh, though.', '2014-12-21 00:02:23.000000', NULL, 1),
(7294518, 1137151, 13077, '<td valign="top">lol. Creative title for sure.</td>', 'lol. Creative title for sure.', '2014-12-21 00:02:45.000000', NULL, 1),
(7294519, 1137119, 13077, '<td valign="top">Good soft light and well shown textures in the petals. Nice tight composition and what negative space is there looks good.</td>', 'Good soft light and well shown textures in the petals. Nice tight composition and what negative space is there looks good.', '2014-12-21 00:03:21.000000', NULL, 1),
(7294520, 1137028, 13077, '<td valign="top">Very nice, has an attractive almost glow to it and great color tones.</td>', 'Very nice, has an attractive almost glow to it and great color tones.', '2014-12-21 00:03:49.000000', NULL, 1),
(7294521, 1137018, 13077, '<td valign="top">A very interesting fern, nicely shown against the dead leaves too.</td>', 'A very interesting fern, nicely shown against the dead leaves too.', '2014-12-21 00:04:15.000000', NULL, 1),
(7294522, 1137065, 13077, '<td valign="top">Brings me back to my childhood and roaming around playing on/in old broken down cars, trucks, tractors, etc. The processing on this one is well done.</td>', 'Brings me back to my childhood and roaming around playing on/in old broken down cars, trucks, tractors, etc. The processing on this one is well done.', '2014-12-21 00:04:56.000000', NULL, 1),
(7294523, 1137155, 13077, '<td valign="top">Oh cool. This is a well chosen angle, also the water drops look good. Nicely done with the pastel colors and the composition too.</td>', 'Oh cool. This is a well chosen angle, also the water drops look good. Nicely done with the pastel colors and the composition too.', '2014-12-21 00:05:39.000000', NULL, 1),
(7294524, 1137132, 13077, '<td valign="top">Well done filling the frame with this. Ordinarily I''d say the light is a little harsh for a flower, but it gives the petals some definition.</td>', 'Well done filling the frame with this. Ordinarily I''d say the light is a little harsh for a flower, but it gives the petals some definition.', '2014-12-21 00:06:42.000000', NULL, 1),
(7294525, 1137118, 13077, '<td valign="top">A lot like what I was seeing (minus the snow on the ground for us) <br/> <br/>I like the contrast and the shapes of the trees, also the fog in the distance.</td>', 'A lot like what I was seeing (minus the snow on the ground for us)  I like the contrast and the shapes of the trees, also the fog in the distance.', '2014-12-21 00:08:02.000000', NULL, 1),
(7294526, 1137152, 13077, '<td valign="top">Beautiful shapes, very elegant.</td>', 'Beautiful shapes, very elegant.', '2014-12-21 00:08:33.000000', NULL, 1),
(7294527, 1137209, 13077, '<td valign="top">Fascinating. Very well done.</td>', 'Fascinating. Very well done.', '2014-12-21 00:08:52.000000', NULL, 1),
(7294528, 1137061, 13077, '<td valign="top">While it''s almost abstract, not sure the blur adds much to it in this case.</td>', 'While it''s almost abstract, not sure the blur adds much to it in this case.', '2014-12-21 00:09:24.000000', NULL, 1),
(7294529, 1137121, 13077, '<td valign="top">I couldn''t blame you for not wanting to reach into that and dig out that strand of whatever that is. But it is a bit distracting.</td>', 'I couldn''t blame you for not wanting to reach into that and dig out that strand of whatever that is. But it is a bit distracting.', '2014-12-21 00:10:06.000000', NULL, 1),
