(7294762, 1136963, 13077, '<td valign="top">Between the colors, the composition and the harsh shadows from the lighting I don''t find it all that visually pleasing.</td>', 'Between the colors, the composition and the harsh shadows from the lighting I don''t find it all that visually pleasing.', '2014-12-21 23:00:58.000000', NULL, 1),
(7294763, 1136833, 13077, '<td valign="top">Very chaotic with the blur, but nicely placed to have the bee sharp.</td>', 'Very chaotic with the blur, but nicely placed to have the bee sharp.', '2014-12-21 23:01:20.000000', NULL, 1),
(7294764, 1137200, 13077, '<td valign="top">Nicely processed. Has a peaceful vibe and it''s attractive and simple.</td>', 'Nicely processed. Has a peaceful vibe and it''s attractive and simple.', '2014-12-21 23:01:50.000000', NULL, 1),
(7294765, 1137160, 13077, '<td valign="top">Maybe a little tight with the crop, but good detail and sharpness.</td>', 'Maybe a little tight with the crop, but good detail and sharpness.', '2014-12-21 23:02:09.000000', NULL, 1),
(7294766, 1137162, 13077, '<td valign="top">I like this composition, and the added texture is interesting. Nice colors.</td>', 'I like this composition, and the added texture is interesting. Nice colors.', '2014-12-21 23:02:31.000000', NULL, 1),
(7294767, 1137186, 13077, '<td valign="top">Some very cool leaves, and the arrangement looks good.</td>', 'Some very cool leaves, and the arrangement looks good.', '2014-12-21 23:02:58.000000', NULL, 1),
(7294769, 1137089, 13077, '<td valign="top">Well, that''s not a typical portrait!<br/>Very intriguing.</td>', 'Well, that''s not a typical portrait!Very intriguing.', '2014-12-21 23:03:27.000000', NULL, 1),
(7294770, 1137049, 13077, '<td valign="top">The color in the background is good, it''s well composed and the touch of pink flowers is nice.</td>', 'The color in the background is good, it''s well composed and the touch of pink flowers is nice.', '2014-12-21 23:03:54.000000', NULL, 1),
(7294771, 1137047, 13077, '<td valign="top">Very strong shapes and textures, attractive photo.</td>', 'Very strong shapes and textures, attractive photo.', '2014-12-21 23:04:16.000000', NULL, 1),
(7294772, 1137069, 13077, '<td valign="top">Good use of shallow DOF and the water droplets are a nice touch.</td>', 'Good use of shallow DOF and the water droplets are a nice touch.', '2014-12-21 23:04:40.000000', NULL, 1),
(7294773, 1137134, 13077, '<td valign="top">Good variety of colors here. I like the composition.</td>', 'Good variety of colors here. I like the composition.', '2014-12-21 23:05:06.000000', NULL, 1),
(7294774, 1136945, 13077, '<td valign="top">Interesting. nicely done lo-fi work.</td>', 'Interesting. nicely done lo-fi work.', '2014-12-21 23:05:36.000000', NULL, 1),
(7294775, 1137164, 13077, '<td valign="top">Very good detail and the texture in the background makes it look sort of like a painting. The just-barely-cropped leaf on the edge bothers me a little.</td>', 'Very good detail and the texture in the background makes it look sort of like a painting. The just-barely-cropped leaf on the edge bothers me a little.', '2014-12-21 23:06:11.000000', NULL, 1),
