(7294778, 1137120, 13077, '<td valign="top">The glow effect is well suited for this one.</td>', 'The glow effect is well suited for this one.', '2014-12-21 23:06:44.000000', NULL, 1),
(7294779, 1137009, 13077, '<td valign="top">What a cool flower! Nicely shot to keep detail in the light parts and the black border complements it well.</td>', 'What a cool flower! Nicely shot to keep detail in the light parts and the black border complements it well.', '2014-12-21 23:07:08.000000', NULL, 1),
(7294780, 1137185, 13077, '<td valign="top">Elegant.</td>', 'Elegant.', '2014-12-21 23:07:18.000000', NULL, 1),
(7294781, 1137177, 13077, '<td valign="top">The tones look very good, and perfect amount of depth of field used.</td>', 'The tones look very good, and perfect amount of depth of field used.', '2014-12-21 23:07:56.000000', NULL, 1),
(7294782, 1137038, 13077, '<td valign="top">Nicely composed and well placed focus. Tones look good too.</td>', 'Nicely composed and well placed focus. Tones look good too.', '2014-12-21 23:08:12.000000', NULL, 1),
(7294783, 1137107, 13077, '<td valign="top">Nice find. I like the overall look of this one.</td>', 'Nice find. I like the overall look of this one.', '2014-12-21 23:08:44.000000', NULL, 1),
(7294784, 1137043, 13077, '<td valign="top">The backlighting is good, and just enough light in the foreground to get a lot of detail. Nicely composed too.</td>', 'The backlighting is good, and just enough light in the foreground to get a lot of detail. Nicely composed too.', '2014-12-21 23:09:24.000000', NULL, 1),
(7294785, 1137176, 13077, '<td valign="top">Elegant in death, set on a softly dismal, chilly sea of brown.</td>', 'Elegant in death, set on a softly dismal, chilly sea of brown.', '2014-12-21 23:10:22.000000', NULL, 1),
(7294786, 1136832, 13077, '<td valign="top">Well captured detail here. I''d never studied one of these ubiquitous things so closely but they really are interesting.</td>', 'Well captured detail here. I''d never studied one of these ubiquitous things so closely but they really are interesting.', '2014-12-21 23:11:02.000000', NULL, 1),
(7294787, 1137066, 13077, '<td valign="top">I like the grittiness in the water and the surreal tones.</td>', 'I like the grittiness in the water and the surreal tones.', '2014-12-21 23:11:30.000000', NULL, 1),
(7294788, 1137129, 13077, '<td valign="top">Not quite in focus, and probably not the best angle to shoot it from either.</td>', 'Not quite in focus, and probably not the best angle to shoot it from either.', '2014-12-21 23:11:49.000000', NULL, 1),
(7294789, 1136914, 13077, '<td valign="top">Cool - they almost look like zebras!</td>', 'Cool - they almost look like zebras!', '2014-12-21 23:12:08.000000', NULL, 1),
(7294790, 1137014, 13077, '<td valign="top">Sharp and well composed - can be challenging to find a clean composition in a mess of dead plants but you pulled it off here.</td>', 'Sharp and well composed - can be challenging to find a clean composition in a mess of dead plants but you pulled it off here.', '2014-12-21 23:12:39.000000', NULL, 1),
(7294791, 1136927, 13077, '<td valign="top">I''m colorful and pretty, eat me!<br/> <br/>Haha, gotcha!</td>', 'I''m colorful and pretty, eat me! Haha, gotcha!', '2014-12-21 23:13:02.000000', NULL, 1),
(7294793, 1136916, 13077, '<td valign="top">A very classy looking arrangement. Nice muted tones, and great textures to shoot it on.</td>', 'A very classy looking arrangement. Nice muted tones, and great textures to shoot it on.', '2014-12-21 23:13:26.000000', NULL, 1),
(7294794, 1136949, 13077, '<td valign="top">The blur and processing style work well on this one.</td>', 'The blur and processing style work well on this one.', '2014-12-21 23:13:50.000000', NULL, 1),
(7294795, 1137090, 13077, '<td valign="top">Nice. You''ve brought a very detailed and shapely subject in front of a beautiful-in-its-own-right-as-an-abstract background, and they work well together.</td>', 'Nice. You''ve brought a very detailed and shapely subject in front of a beautiful-in-its-own-right-as-an-abstract background, and they work well together.', '2014-12-21 23:14:52.000000', NULL, 1),
(7294796, 1137020, 13077, '<td valign="top">Very punchy colors and good detail in the petals.</td>', 'Very punchy colors and good detail in the petals.', '2014-12-21 23:15:11.000000', NULL, 1),
(7294797, 1137153, 13077, '<td valign="top">Fascinating. Visually, works very well. I like it.</td>', 'Fascinating. Visually, works very well. I like it.', '2014-12-21 23:16:01.000000', NULL, 1);
